// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DefenseReport) predicate.DefenseReport {
	return predicate.DefenseReport(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DefenseReport) predicate.DefenseReport {
	return predicate.DefenseReport(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DefenseReport) predicate.DefenseReport {
	return predicate.DefenseReport(sql.NotPredicates(p))
}
